sys_script.script:
(function executeRule(current, previous) {

    var appointmentId = current.getUniqueValue();

    // Check if Invoice already exists
    var invoice = new GlideRecord('x_2223823_apollo_0_invoice');

    invoice.addQuery('appointment', appointmentId);
    invoice.query();

    if (invoice.next()) {
        current.setValue('invoice', invoice.getUniqueValue());
        return;
    }

    // Create new Invoice
    invoice.initialize();

    invoice.setValue('appointment', appointmentId);
    invoice.setValue('patient', current.getValue('patient'));
    invoice.setValue('hospital', current.getValue('hospital'));

    invoice.setValue('patient_type', 'opd');

    invoice.setValue('total_amount', 0);
    invoice.setValue('paid_amount', 0);
    invoice.setValue('balance_amount', 0);

    invoice.setValue('final_invoice', false);

    var invoiceId = invoice.insert();

    // Link Invoice with Appointment
    if (invoiceId) {
        current.setValue('invoice', invoiceId);
    }

})(current, previous);
